def wrap(s: str, width: int = 15) -> list[str]:
    lines=textwrap.wrap(s, width, break_long_words=False, break_on_hyphens=False)
    if len(lines)>2: raise ValueError(f"label too wide for map: {s!r}")
    return lines

def svg(lesson: dict, lang: str) -> str:
    idx=LANGS.index(lang)
    title=lesson['title'][idx]
    title_lines=textwrap.wrap(title, 48, break_long_words=False)
    if len(title_lines)>2: raise ValueError(f"title too long: {title}")
    number=int(lesson['stem'][:2])
    labels=lesson['support'] if lang=='kz' else SUPPORT_LABELS[number][lang]
    positions=[(65+373*i,335) for i in range(4)]
    colors=['#0e7490','#b65b37','#6b5aa8','#25816c']
    cards=[]
    for i,(x,y) in enumerate(positions):
        ys=''.join(f'<text x="{x+170}" y="{y+146+j*43}" text-anchor="middle" font-size="27" fill="#17344a" font-weight="700">{html.escape(line)}</text>' for j,line in enumerate(wrap(labels[i])))
        example_lines=wrap(MAP_EXAMPLES[number][i],22)
        examples=''.join(f'<text x="{x+170}" y="{y+242+j*24}" text-anchor="middle" font-size="18" fill="#526b79">{html.escape(line)}</text>' for j,line in enumerate(example_lines))
        # An explicit numbered role makes the diagram useful even without colour.
        cards.append(f'<g filter="url(#shadow)"><rect x="{x}" y="{y}" width="340" height="280" rx="24" fill="#fff" stroke="{colors[i]}" stroke-width="4"/><rect x="{x}" y="{y}" width="340" height="56" rx="22" fill="{colors[i]}"/><text x="{x+28}" y="{y+39}" font-size="28" fill="white" font-weight="700">0{i+1}</text>{ys}<path d="M{x+34} {y+207}h272" stroke="#d3e0e7" stroke-width="2"/>{examples}</g>')
    tx=''.join(f'<text x="85" y="{156+i*52}" font-size="40" fill="#17344a" font-weight="800">{html.escape(line)}</text>' for i,line in enumerate(title_lines))
    # A single left-to-right line prevents ambiguous jumps across the grid.
    arrows=''.join(f'<path d="M{65+373*i+346} 475h20"/>' for i in range(3))
    caption={'ru':'СЛУШАЙ  /  ПРОВЕРЯЙ  /  ГОВОРИ','kz':'ТЫҢДА  /  ТЕКСЕР  /  АЙТ','en':'LISTEN  /  CHECK  /  SPEAK'}[lang]
    heading={'ru':'ОПОРНАЯ КАРТА','kz':'ТІРЕК КАРТА','en':'SUPPORT MAP'}[lang]
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900" role="img" aria-label="{html.escape(title)}"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d1e4ed"/></pattern><filter id="shadow" x="-15%" y="-20%" width="135%" height="150%"><feDropShadow dx="0" dy="10" stdDeviation="13" flood-color="#17364e" flood-opacity=".18"/></filter><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9Z" fill="#2e5a72"/></marker></defs><rect width="1600" height="900" fill="#edf7f7"/><rect width="1600" height="900" fill="url(#grid)"/><rect x="45" y="45" width="1510" height="810" rx="28" fill="#f9fcfc" stroke="#bfd5dd" stroke-width="3"/><text x="85" y="103" font-size="27" font-weight="800" fill="#ba433c">{heading} · {lesson['stem'][:2]}</text>{tx}<g font-family="DejaVu Sans,Arial,sans-serif">{''.join(cards)}</g><g fill="none" stroke="#2e5a72" stroke-width="5" marker-end="url(#arrow)">{arrows}</g><rect x="425" y="755" width="750" height="46" rx="15" fill="#17364e"/><text x="800" y="787" text-anchor="middle" fill="white" font-size="23" font-weight="700" font-family="DejaVu Sans,Arial,sans-serif">{caption}</text></svg>'''

def render(lesson: dict, lang: str, following: dict | None, by_phrase: dict) -> str:
    idx=LANGS.index(lang); ui=UI[lang]; c=COMMON[lang]; number=int(lesson['stem'][:2])
    parts=[f"# {lesson['title'][idx]}","",f"_Lead (summary):_ **{lesson['lead'][idx]}**","",f"## {ui[0]}","",c['map'],"",f"![{lesson['title'][idx]}](/static/course/kazakh-language/map-{lesson['map']}-{lang}.svg)","",f"## {ui[1]}","",lesson['scene'][idx],"",f"## {ui[2]}",""]
    for phrase,ru,kz,en in lesson['phrases']:
        parts.extend((f"[{ui[16]}: {phrase}](/static/course/kazakh-language/audio/{by_phrase[phrase]['file']}) — {(ru,kz,en)[idx]}",""))
    sections=[(ui[3],c['listen']),(ui[4],lesson['model'][idx]),(ui[5],'```kazakh\n'+' → '.join(lesson['support'])+'\n```'),(ui[6],lesson['limit'][idx]),(ui[7],c['predict']),(ui[8],c['recall']),(ui[9],lesson['error'][idx]),(ui[10],TRANSFER[number][idx]),(ui[11],c['project']+' '+PROJECT_STEP[number][idx]),(ui[12],lesson['task'][idx])]
    for heading,body in sections: parts.extend((f"## {heading}","",body,""))
    parts.extend((f"## {ui[13]}","",*('- '+x for x in c['repeat'])))
    if following: parts.extend(("",f"[{ui[14]}: {following['title'][idx]}](/read/kazakh-language-{following['stem']}?lang={lang})"))
    else: parts.extend(("",f"[{ui[15]}](/course/kazakh-language?lang={lang})"))
    return '\n'.join(parts)+'\n'

def main() -> None:
    assert len(LESSONS)==8 and [int(x['stem'][:2]) for x in LESSONS]==list(range(57,65))
    data=json.loads((AUDIO/'manifest.json').read_text(encoding='utf-8'))
    rows=data['recordings'];by_phrase={r['phrase']:r for r in rows};next_id=max(int(r['id'][3:]) for r in rows)+1
    for lesson in LESSONS:
        for phrase,*_ in lesson['phrases']:
            row=by_phrase.get(phrase)
            if not row:
                row={'id':f'kz-{next_id:03d}','phrase':phrase,'file':f'kz-{next_id:03d}.wav','status':'candidate_review','lessons':[]}
                rows.append(row);by_phrase[phrase]=row;next_id+=1
            for lang in LANGS:
                name=lesson['stem']+('' if lang=='ru' else '-'+lang)+'.md'
                if name not in row['lessons']: row['lessons'].append(name)
            row['lessons'].sort()
    (AUDIO/'manifest.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    for i,lesson in enumerate(LESSONS):
        for lang in LANGS:
            suffix='' if lang=='ru' else '-'+lang
            (LESSONS_DIR/(lesson['stem']+suffix+'.md')).write_text(render(lesson,lang,LESSONS[i+1] if i<7 else None,by_phrase),encoding='utf-8')
            (STATIC/(f"map-{lesson['map']}-{lang}.svg")).write_text(svg(lesson,lang),encoding='utf-8')
    print(f"Prepared {len(LESSONS)} lessons, 24 translations, 24 diagrams; {sum(r['status']=='candidate_review' for r in rows)} audio candidates")

if __name__=='__main__': main()
